/* iPlus 1.2.0: article pagination and clipped fixed-position advertising */
.iplus-article-parallax{display:block;clear:both;margin:25px 0;background:#0d0d0d;font:10px/15px Arial,sans-serif;color:#fff}
.iplus-article-parallax .sm-px{position:relative;height:300px;clip-path:inset(0 0 0 0);overflow:hidden;background:#0d0d0d}
.iplus-article-parallax .sm-px-in{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:300px;max-width:calc(100vw - 20px);line-height:0}
.is-post #post-ad-holder{width:300px;max-width:100%}
.iplus-article-parallax .sm-px-in .widget{margin:0;padding:0}.iplus-article-parallax .ad-placeholder{width:300px;height:600px;max-width:100%;margin:0 auto}
.parallax-caption{height:15px;text-align:center;text-transform:uppercase;background:#222;color:#fff;font:9px/15px Arial,sans-serif;letter-spacing:.1px}
.article-pages{scroll-margin-top:115px;outline:none}.article-page[hidden]{display:none!important}.article-page{min-width:0;overflow-wrap:anywhere}
.article-hero figcaption p{margin:0}
.article-pagination{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:30px 0;font:14px/20px var(--font-body)}
.pagination-label{font-weight:700}.pagination-controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.page-link{display:inline-flex;min-width:30px;height:30px;align-items:center;justify-content:center;padding:0 10px;border:1px solid var(--border);border-radius:5px;background:var(--soft);color:var(--text);font-weight:700;font-size:12px}
.page-link.current,.page-link:hover{background:var(--primary);border-color:var(--primary);color:white}.article-pagination .page-link:focus-visible{outline:2px solid var(--primary);outline-offset:3px}
